     * «включил Tor» и «Tor работает» лежат десятки секунд bootstrap
     * и публикации сервиса, и всё это время §5.4 его не выбирает.
     * «Поднимается» — правда, «не работает» — нет.
     */
    @Throws(RatatoskException::class)override fun `transportReady`(`transport`: FfiTransport): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithHandle {
    uniffiRustCallWithError(RatatoskException) { _status ->
    UniffiLib.uniffi_ratatosk_ffi_fn_method_ratatoskclient_transport_ready(
        it,
        
        FfiConverterTypeFfiTransport.lower(`transport`),_status)
}
    }
    )
    }
    

    
    /**
     * Ключ нашего узла в меше, если он назван (0.2). Пусто — меша нет.
     *
     * Читается из своей карточки: там он и живёт. Нужен экрану настроек,
     * чтобы показать человеку **действующее** имя — не то, что он ввёл,
     * а то, что уехало собеседникам, — и рядом выведенный адрес для сверки
     * с `yggdrasilctl getSelf`. В режиме своего узла это имя мы назвали
     * себе сами, и вводить его человеку было негде.
     */
    @Throws(RatatoskException::class)override fun `yggKey`(): kotlin.ByteArray {
            return FfiConverterByteArray.lift(
    callWithHandle {
    uniffiRustCallWithError(RatatoskException) { _status ->
    UniffiLib.uniffi_ratatosk_ffi_fn_method_ratatoskclient_ygg_key(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * Текущий режим меша.
     */
    @Throws(RatatoskException::class)override fun `yggMode`(): FfiYggMode {
            return FfiConverterTypeFfiYggMode.lift(
    callWithHandle {
    uniffiRustCallWithError(RatatoskException) { _status ->
    UniffiLib.uniffi_ratatosk_ffi_fn_method_ratatoskclient_ygg_mode(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * Пиры встроенного узла, как их назвал человек.
     */
    @Throws(RatatoskException::class)override fun `yggPeers`(): List<kotlin.String> {
            return FfiConverterSequenceString.lift(
    callWithHandle {
    uniffiRustCallWithError(RatatoskException) { _status ->
    UniffiLib.uniffi_ratatosk_ffi_fn_method_ratatoskclient_ygg_peers(
        it,
        _status)
}
    }
    )
    }
    

    

    


    
    companion object {
        
    /**
     * Открывает или создаёт хранилище по пути.
     *
     * `pin` — `None`, если пользователь отказался от PIN. В этом случае
     * клиент **обязан** показать [`no_pin_warning`]: §8.6 разрешает отказ,
     * но ключ базы лежит тогда в самой базе открыто, и содержимое доступно
     * любому, кто получил файл.
     *
     * `device_key` — 32 байта из хранилища ключей ОС (Android Keystore).
     * Их генерирует и хранит клиент; ядро их не запоминает, а только
     * выводит из них ключ базы вместе с солью. Что это даёт и чем за это
     * платят:
     *
     * * с секретом устройства база **не открывается на другом телефоне** —
     * ни с PIN, ни без. Это защита от того, у кого файл, но нет аппарата;
     * * и это же означает, что **потеря телефона — потеря переписки**.
     * Секрет из Keystore не восстанавливается ни резервной фразой,
     * ни бэкапом. Сказать об этом человеку надо до, а не после;
     * * вместе с PIN — защита от обоих сразу: файл бесполезен без аппарата,
     * аппарат — без PIN.
     *
     * Секрет обязан быть ровно 32 байта. Всё остальное — отказ: короткий
     * секрет означает, что клиент положил туда не то, и молча вывести
     * из этого ключ базы значило бы изобразить защиту.
     *
     * Неверный PIN возвращает [`RatatoskError::Locked`] и **не** заводит
     * новую личность: молчаливый старт с чистого листа выглядит как
     * потерянная переписка.
     */
    @Throws(RatatoskException::class) fun `open`(`dbPath`: kotlin.String, `pin`: kotlin.String?, `deviceKey`: kotlin.ByteArray?, `displayName`: kotlin.String): RatatoskClient {
            return FfiConverterTypeRatatoskClient.lift(
    uniffiRustCallWithError(RatatoskException) { _status ->
    UniffiLib.uniffi_ratatosk_ffi_fn_constructor_ratatoskclient_open(
    
        
        FfiConverterString.lower(`dbPath`),
        FfiConverterOptionalString.lower(`pin`),
        FfiConverterOptionalByteArray.lower(`deviceKey`),
        FfiConverterString.lower(`displayName`),_status)
}
    )
    }
    

        
    }
    
}


/**
 * @suppress
 */
public object FfiConverterTypeRatatoskClient: FfiConverter<RatatoskClient, Long> {
    override fun lower(value: RatatoskClient): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): RatatoskClient {
        return RatatoskClient(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): RatatoskClient {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: RatatoskClient) = 8UL

    override fun write(value: RatatoskClient, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


// This template implements a class for working with a Rust struct via a handle
// to the live Rust struct on the other side of the FFI.
//
// There's some subtlety here, because we have to be careful not to operate on a Rust
// struct after it has been dropped, and because we must expose a public API for freeing
// theq Kotlin wrapper object in lieu of reliable finalizers. The core requirements are:
//
//   * Each instance holds an opaque handle to the underlying Rust struct.
//     Method calls need to read this handle from the object's state and pass it in to
//     the Rust FFI.
//
//   * When an instance is no longer needed, its handle should be passed to a
//     special destructor function provided by the Rust FFI, which will drop the
//     underlying Rust struct.
//
//   * Given an instance, calling code is expected to call the special
//     `destroy` method in order to free it after use, either by calling it explicitly
//     or by using a higher-level helper like the `use` method. Failing to do so risks
//     leaking the underlying Rust struct.
//
//   * We can't assume that calling code will do the right thing, and must be prepared
//     to handle Kotlin method calls executing concurrently with or even after a call to
//     `destroy`, and to handle multiple (possibly concurrent!) calls to `destroy`.
//
//   * We must never allow Rust code to operate on the underlying Rust struct after
//     the destructor has been called, and must never call the destructor more than once.
//     Doing so may trigger memory unsafety.
//
//   * To mitigate many of the risks of leaking memory and use-after-free unsafety, a `Cleaner`
//     is implemented to call the destructor when the Kotlin object becomes unreachable.
//     This is done in a background thread. This is not a panacea, and client code should be aware that
//      1. the thread may starve if some there are objects that have poorly performing
//     `drop` methods or do significant work in their `drop` methods.
//      2. the thread is shared across the whole library. This can be tuned by using `android_cleaner = true`,
//         or `android = true` in the [`kotlin` section of the `uniffi.toml` file](https://mozilla.github.io/uniffi-rs/kotlin/configuration.html).
//
// If we try to implement this with mutual exclusion on access to the handle, there is the
// possibility of a race between a method call and a concurrent call to `destroy`:
//
//    * Thread A starts a method call, reads the value of the handle, but is interrupted
//      before it can pass the handle over the FFI to Rust.
//    * Thread B calls `destroy` and frees the underlying Rust struct.
//    * Thread A resumes, passing the already-read handle value to Rust and triggering
//      a use-after-free.
//
// One possible solution would be to use a `ReadWriteLock`, with each method call taking
// a read lock (and thus allowed to run concurrently) and the special `destroy` method
// taking a write lock (and thus blocking on live method calls). However, we aim not to
// generate methods with any hidden blocking semantics, and a `destroy` method that might
// block if called incorrectly seems to meet that bar.
//
// So, we achieve our goals by giving each instance an associated `AtomicLong` counter to track
// the number of in-flight method calls, and an `AtomicBoolean` flag to indicate whether `destroy`
// has been called. These are updated according to the following rules:
//
//    * The initial value of the counter is 1, indicating a live object with no in-flight calls.
//      The initial value for the flag is false.
//
//    * At the start of each method call, we atomically check the counter.
//      If it is 0 then the underlying Rust struct has already been destroyed and the call is aborted.
//      If it is nonzero them we atomically increment it by 1 and proceed with the method call.
//
//    * At the end of each method call, we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
//    * When `destroy` is called, we atomically flip the flag from false to true.
//      If the flag was already true we silently fail.
//      Otherwise we atomically decrement and check the counter.
//      If it has reached zero then we destroy the underlying Rust struct.
//
// Astute readers may observe that this all sounds very similar to the way that Rust's `Arc<T>` works,
// and indeed it is, with the addition of a flag to guard against multiple calls to `destroy`.
//
// The overall effect is that the underlying Rust struct is destroyed only when `destroy` has been
// called *and* all in-flight method calls have completed, avoiding violating any of the expectations
// of the underlying Rust code.
//
// This makes a cleaner a better alternative to _not_ calling `destroy()` as
// and when the object is finished with, but the abstraction is not perfect: if the Rust object's `drop`
// method is slow, and/or there are many objects to cleanup, and it's on a low end Android device, then the cleaner
// thread may be starved, and the app will leak memory.
//
// In this case, `destroy`ing manually may be a better solution.
//
// The cleaner can live side by side with the manual calling of `destroy`. In the order of responsiveness, uniffi objects
// with Rust peers are reclaimed:
//
// 1. By calling the `destroy` method of the object, which calls `rustObject.free()`. If that doesn't happen:
// 2. When the object becomes unreachable, AND the Cleaner thread gets to call `rustObject.free()`. If the thread is starved then:
// 3. The memory is reclaimed when the process terminates.
//
// [1] https://stackoverflow.com/questions/24376768/can-java-finalize-an-object-when-it-is-still-in-scope/24380219
//


/**
 * Второй экран телефона — то, что держит Kotlin (§13.4).
 *
 * Устроен так же, как [`RatatoskClient`](crate::RatatoskClient), и по той же
 * причине: методы через UniFFI синхронные, а драйвер асинхронный. Поэтому
 * внутри живёт свой поток с рантаймом, а наружу уходит ручка из каналов.
 *
 * Уничтожение объекта закрывает канал команд, драйвер выходит из цикла,
 * поток завершается. Отдельного `close` нет намеренно.
 *
 * # Чего у него нет и не появится
 *
 * Ни базы, ни личности, ни истории. Всё, что он показывает, приехало
 * с телефона в этой связи или лежит в дисковом кэше с прошлой — и во втором
 * случае об этом сказано полем `fresh`. Выключенный телефон означает
 * нерабочий десктоп, и изображать обратное §14 запрещает прямо.
 */
public interface RatatoskCompanionInterface {
    
    /**
     * Просит **телефон** начать качать вложение у собеседника.
     *
     * Порядок обязателен и его надо объяснять человеку: сперва телефон
     * забирает файл у собеседника, и только потом
     * [`RatatoskCompanion::save_file`] переносит его сюда. До `accept_file`
     * забирать нечего.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `acceptFile`(`fileId`: kotlin.ByteArray)
    
    /**
     * Добавляет к себе того, чья карточка приехала этим сообщением.
     *
     * **Называется сообщение, а не карточка.** Байты лежат на телефоне
     * и границу не пересекают ни туда, ни обратно: присланная с десктопа
     * «карточка» была бы ключом, назначенным десктопом.
     *
     * Сверки (§4.2) это не даёт и дать не может: она делается голосом
     * при встрече, а не нажатием в окне.
     *
     * # Errors
     *
     * Идентификатор не той длины; карточки в этом сообщении нет —
     * телефон скажет словами.
     */
    fun `addSharedContact`(`msgId`: kotlin.ByteArray)
    
    /**
     * Спрашивает аватарку — контакта или свою.
     *
     * `chat_id = None` — своя. Ответ приедет событием
     * [`FfiCompanionEvent::Avatar`], байтами, и мера у этого та же, что
     * у превью: лицо не больше 32 КиБ.
     *
     * **Звать стоит по метке, а не на каждый показ списка.**
     * [`FfiCompanionChat::avatar_ms`] говорит, изменилось ли лицо
     * с прошлого раза; спросив без этой проверки, окно возит по сети
     * тридцать два килобайта на контакт при каждом обновлении списка.
     * Свою — раз за подключение: метки для сравнения у неё нет.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `avatar`(`chatId`: kotlin.ByteArray?)
    
    /**
     * Прекращает начатое сохранение и убирает недописанный файл.
     *
     * Обрывок стирается всегда, и это не уборка ради чистоты: недокачанный
     * файл на диске выглядит ровно как докачанный (§14).
     *
     * # Errors
     *
     * Компаньон остановлен.
     */
    fun `cancelSave`()
    
    /**
     * Передумывает отправлять: выгруженное на телефоне выбрасывается.
     *
     * # Errors
     *
     * Компаньон остановлен.
     */
    fun `cancelSend`()
    
    /**
     * Просит список чатов.
     *
     * Ответ приедет событием [`FfiCompanionEvent::Chats`], а не отсюда:
     * считает его телефон, и ждать его синхронно значило бы держать окно
     * на круге по сети.
     *
     * # Errors
     *
     * Компаньон остановлен.
     */
    fun `chats`()
    
    /**
     * Очищает чат **у себя**.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `clearChat`(`chatId`: kotlin.ByteArray)
    
    /**
     * Заводит группу (§11).
     *
     * **Перед вызовом обязателен `group_join_notice()`.** §11.5 требует
     * сказать при создании, что участники увидят onion- и chatmail-адреса
     * друг друга; сказанное после — уже не предупреждение, а отменить это
     * нельзя ничем. Текст — свободная функция тех же биндингов: проводом
     * он не едет, потому что это константа, а не сведение о телефоне,
     * и телефон не может проверить, показали ли его.
     *
     * Идентификатор новой группы придёт событием
     * [`FfiCompanionEvent::GroupCreated`] — им и открывают чат.
     *
     * Пределы названия те же, что на телефоне: непустое после обрезки
     * краёв и не длиннее `max_group_title_chars()`. Поле ввода обязано
     * останавливать **до** нажатия, а не показывать отказ после.
     *
     * # Errors
     *
     * Остановленный компаньон.
     */
    fun `createGroup`(`title`: kotlin.String)
    
    /**
     * Отказывается от вложения совсем: приехавшее на телефоне стирается.
     *
     * Вложение исчезнет событием [`FfiCompanionEvent::FileGone`], а само
     * сообщение с текстом останется.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `declineFile`(`fileId`: kotlin.ByteArray)
    
    /**
     * Удаляет сообщения **у себя**.
     *
     * Собеседник их сохраняет; чтобы попросить и его, есть
     * [`RatatoskCompanion::retract_messages`]. Разницу человеку надо
     * показать до нажатия, а не после (§14).
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `deleteMessages`(`chatId`: kotlin.ByteArray, `msgIds`: List<kotlin.ByteArray>)
    
    /**
     * Ключ, которым терминал объявляется в эфире.
     *
     * Не личность и не контакт: он выведен из секрета сопряжения, и телефон
     * ищет в эфире именно его (§5.1). Вторая половина той же строки, что
     * и [`RatatoskCompanion::port`].
     */
    fun `desktopIk`(): kotlin.ByteArray
    
    /**
     * Как эта запись называется на телефоне (§13.4).
     *
     * Тот же идентификатор, что показывает список устройств на телефоне.
     * Показать его рядом с «подключено» стоит: человек, у которого два
     * компьютера, иначе не знает, какой из них отзывает.
     */
    fun `deviceId`(): kotlin.ByteArray
    
    /**
     * Заменяет текст своего сообщения.
     *
     * Окно правки (неделя) считается по часам **телефона** (§9.1): часы
     * ноутбука к этому порядку не относятся, и проверять их здесь нечем.
     * Просроченная правка вернётся [`FfiCompanionEvent::Refused`] со словами.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `editMessage`(`chatId`: kotlin.ByteArray, `msgId`: kotlin.ByteArray, `text`: kotlin.String)
    
    /**
     * Исключает участника из группы (§11.2).
     *
     * **Только создатель** — кнопку стоит показывать, лишь когда в составе
     * есть строка с `mine && owner`. **Перед вызовом обязателен
     * `eviction_notice()`** (§11.4): исключённый сохранит доступ к прошлой
     * переписке, и отменить это нельзя ничем.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `evictFromGroup`(`chatId`: kotlin.ByteArray, `memberChatId`: kotlin.ByteArray)
    
    /**
     * Пересылает сообщения в другой чат.
     *
     * Автор при пересылке **не сохраняется** — ни в проводе, ни на экране:
     * «переслано от N» было бы утверждением, которое никто не проверит.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `forwardMessages`(`chatId`: kotlin.ByteArray, `msgIds`: List<kotlin.ByteArray>)
    
    /**
     * Просит страницу истории.
     *
     * `before` — `None` для конца ленты, иначе `msg_id` самого старого
     * из показанных. Ответ — [`FfiCompanionEvent::History`].
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `history`(`chatId`: kotlin.ByteArray, `limit`: kotlin.UInt, `before`: kotlin.ByteArray?)
    
    /**
     * Зовёт человека в группу (§11.2).
     *
     * Приглашать вправе **любой** участник, а не только создатель.
     * Приглашаемый адресуется идентификатором своего личного чата —
     * тем же, каким окно ему пишет: он есть и в строке списка чатов,
     * и в [`FfiCompanionMember::chat_id`].
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `inviteToGroup`(`chatId`: kotlin.ByteArray, `memberChatId`: kotlin.ByteArray)
    
    /**
     * Выходит из группы.
     *
     * **Перед вызовом обязателен `leave_notice()`**, а если выходит
     * создатель (в составе есть строка `mine && owner`) — ещё и
     * `owner_leave_notice()`: после его ухода группу нельзя ни
     * переименовать, ни исключить из неё, ни сменить ей картинку.
     *
     * Переписка остаётся, и группа остаётся в списке чатов: уход
     * из разговора не стирает сказанное. Вернуть вышедшего вправе любой
     * участник.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `leaveGroup`(`chatId`: kotlin.ByteArray)
    
    /**
     * Отмечает прочитанным до этого сообщения включительно (§9.4).
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `markRead`(`chatId`: kotlin.ByteArray, `upTo`: kotlin.ByteArray)
    
    /**
     * Спрашивает состав группы (§11.2).
     *
     * Ответ придёт событием [`FfiCompanionEvent::Members`]. Отдельным
     * вызовом, а не полем списка чатов: до тридцати двух участников
     * на группу, а список читается на каждый показ экрана — состав же
     * нужен одному окну, тому, где открыты сведения о группе.
     *
     * У личного чата ответ пуст, и спрашивать его незачем: состав
     * переписки двоих — её заголовок.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `members`(`chatId`: kotlin.ByteArray)
    
    /**
     * Останавливает приём, **не отказываясь**: приехавшее остаётся.
     *
     * `accept_file` продолжит с той же дырки. Показывать это надо словами
     * «остановлено, продолжить», а не «отменено»: прочитавший «отменено»
     * не станет продолжать то, что считает потерянным.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `pauseFile`(`fileId`: kotlin.ByteArray)
    
    /**
     * Имя телефона из ссылки сопряжения.
     *
     * Выбрал его владелец телефона, и проверить его нечем — как и всякое
     * имя из карточки (§4.1). Для заголовка окна этого достаточно.
     */
    fun `phoneName`(): kotlin.String
    
    /**
     * Порт, который занял терминал.
     *
     * Нужен ровно для одного: если телефон не находит десктоп сам, человек
     * вводит на телефоне адрес руками, и в нём этот порт.
     */
    fun `port`(): kotlin.UShort
    
    /**
     * Просит превью вложения (§10.3).
     *
     * Ответ приедет событием [`FfiCompanionEvent::FilePreview`] — байтами,
     * а не путём, и это единственное место, где содержимое файла доходит
     * до окна целиком. Оправдано мерой: превью не больше 32 КиБ, тогда как
     * кусок файла — мебибайт.
     *
     * Спрашивать стоит там, где [`FfiCompanionAttachment::has_preview`]
     * говорит «есть», и **только для того, что на экране сейчас**. Просьба
     * на всю страницу вперёд — это те самые мегабайты, ради которых превью
     * и вынесли из страницы; вдобавок каждая из них занимает круг по сети.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `preview`(`fileId`: kotlin.ByteArray)
    
    /**
     * Переименовывает группу. Только создатель.
     *
     * Новое название приедет новостью `ChatsChanged` — список чатов
     * перечитывается целиком.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `renameGroup`(`chatId`: kotlin.ByteArray, `title`: kotlin.String)
    
    /**
     * Удаляет у себя и **просит** собеседника сделать то же.
     *
     * Просьба — и ничего больше: выполнит её клиент собеседника или нет,
     * проверить нельзя. Обещать «сообщение удалено у всех» §14 запрещает.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `retractMessages`(`chatId`: kotlin.ByteArray, `msgIds`: List<kotlin.ByteArray>)
    
    /**
     * Забирает вложение с телефона в файл по этому пути.
     *
     * Байты пишет ядро: путь, а не поток. `chunk_total` берётся
     * из [`FfiCompanionAttachment::chunk_total`] — своей разбивки у десктопа
     * нет и быть не должно, она обязана совпадать с §10.2.
     *
     * Забирать имеет смысл то, что телефон уже собрал целиком
     * (`have_chunks == chunk_total`); начатое раньше остановится на первой
     * же дырке. Конец — [`FfiCompanionEvent::FileSaved`].
     *
     * **Одно вложение за раз.** Второй вызов до конца первого вернётся
     * отказом словами, а не встанет в очередь.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `saveFile`(`fileId`: kotlin.ByteArray, `chunkTotal`: kotlin.ULong, `path`: kotlin.String)
    
    /**
     * Отправляет файлы с этого компьютера **одним сообщением**.
     *
     * От одного до [`max_files_per_message`](crate::max_files_per_message)
     * вложений. Порядок списка — тот, в каком их увидит собеседник, и менять
     * его ядро не станет.
     *
     * Читает файлы ядро, по куску за раз и по одному файлу, — значит,
     * до конца отправки они должны оставаться на месте. Подпись пустая
     * законна: файлы сами по себе тоже сообщение.
     *
     * Идёт это в три шага на каждый файл: телефон отводит место, принимает
     * куски, — и только когда собраны **все**, отправляет одно сообщение.
     * Сообщение с половиной вложений хуже неотправленного, поэтому между
     * вторым шагом и третьим не уходит ничего. Конец —
     * [`FfiCompanionEvent::FilesSent`].
     *
     * Превью у каждого файла **готовит клиент**, ровно как на телефоне
     * (`FfiOutgoingFile::preview`): декодер изображений — большая поверхность
     * атаки, и в процессе, который держит ключи, ему делать нечего.
     * Масштабировать и перекодировать исходник — работа Kotlin; ядро
     * проверяет только длину. `None` законно и обычно: файл не картинка,
     * декодер не справился, человек не захотел, — тогда собеседник решает
     * по имени файла, как решал всегда.
     *
     * **Одно сообщение за раз.** Второй вызов до конца первого вернётся
     * событием `Refused`.
     *
     * Превью больше предела, пустой список и список длиннее предела
     * отвергаются **событием** `Refused`, а не отказом отсюда: правила живут
     * в ядре, и второе место с теми же числами разошлось бы с первым молча.
     * Сколько можно, скажут [`max_preview_bytes`](crate::max_preview_bytes)
     * и [`max_files_per_message`](crate::max_files_per_message).
     *
     * # Errors
     *
     * Негодный идентификатор чата или остановленный компаньон.
     */
    fun `sendFiles`(`chatId`: kotlin.ByteArray, `files`: List<FfiCompanionOutgoing>, `text`: kotlin.String)
    
    /**
     * Отвечает на сообщение.
     *
     * Едет ссылка, а не отрывок цитаты: цитату рисует та сторона, у которой
     * есть своя копия.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `sendReply`(`chatId`: kotlin.ByteArray, `replyTo`: kotlin.ByteArray, `text`: kotlin.String)
    
    /**
     * Отправляет текст в чат.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `sendText`(`chatId`: kotlin.ByteArray, `text`: kotlin.String)
    
    /**
     * Ставит или снимает **свою** аватарку (§4.2).
     *
     * `None` — снять. Байты готовит клиент, как и превью: масштабирование
     * и перекодирование — работа платформенного декодера, а не ядра,
     * которое держит ключи. Предел — `max_avatar_bytes()`; картинку больше
     * провод отвергнет, а негодный формат вернётся `Refused` со словами.
     *
     * **Чужую аватарку поменять нельзя ни отсюда, ни откуда-либо ещё.**
     * Лицо контакта приходит от него самого по установленной сессии.
     *
     * Разошлёт её сверенным контактам телефон — рассылка отсюда невозможна
     * в принципе: сессии с контактами есть только у него (§13.4). Ответ
     * приедет событием [`FfiCompanionEvent::AvatarChanged`] с `chat_id:
     * None`; его получат **все** сопряжённые десктопы, включая этот.
     *
     * # Errors
     *
     * Остановленный компаньон.
     */
    fun `setAvatar`(`bytes`: kotlin.ByteArray?)
    
    /**
     * Включает или выключает снимок переписки на диске.
     *
     * `None` **стирает** уже лежащий файл, а не перестаёт его обновлять:
     * человек, снявший галочку, имел в виду «здесь этого не должно быть».
     *
     * Что сказать ему при включении, сказано у [`RatatoskCompanion::open`],
     * и сказать это обязательно.
     *
     * # Errors
     *
     * Компаньон остановлен.
     */
    fun `setCachePath`(`path`: kotlin.String?)
    
    /**
     * Ставит или снимает аватарку группы. Только создатель.
     *
     * `None` — снять. Пределы те же, что у своей: `max_avatar_bytes()`,
     * PNG, JPEG или WebP; масштабирует и перекодирует окно.
     *
     * **Правила §4.2 у группы нет**: картинку видят все участники,
     * сверенные и нет. Ответ приедет новостью
     * [`FfiCompanionEvent::AvatarChanged`] с `chat_id` этой группы.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `setGroupAvatar`(`chatId`: kotlin.ByteArray, `bytes`: kotlin.ByteArray?)
    
    /**
     * Подписывает окно на события.
     */
    fun `setObserver`(`observer`: CompanionObserver)
    
    /**
     * Ставит или снимает реакцию. Пустая строка снимает.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    fun `setReaction`(`chatId`: kotlin.ByteArray, `msgId`: kotlin.ByteArray, `emoji`: kotlin.String)
    
    /**
     * Делится в чате карточкой человека (§4.1).
     *
     * Человек назван идентификатором **личного чата** с ним — тем же,
     * каким его называет состав группы (`FfiCompanionMember::chat_id`).
     * `None` означает «своей карточкой»: личного чата с самим собой
     * не бывает, а поделиться собой — обычное дело.
     *
     * Работает и в группу: телефон зовёт тот же обработчик, что и у своей
     * команды, а тот с прошлой поставки умеет обе стороны.
     *
     * # Errors
     *
     * Идентификатор не той длины; телефон отказал словами.
     */
    fun `shareContact`(`chatId`: kotlin.ByteArray, `whoChatId`: kotlin.ByteArray?)
    
    companion object
}

/**
 * Второй экран телефона — то, что держит Kotlin (§13.4).
 *
 * Устроен так же, как [`RatatoskClient`](crate::RatatoskClient), и по той же
 * причине: методы через UniFFI синхронные, а драйвер асинхронный. Поэтому
 * внутри живёт свой поток с рантаймом, а наружу уходит ручка из каналов.
 *
 * Уничтожение объекта закрывает канал команд, драйвер выходит из цикла,
 * поток завершается. Отдельного `close` нет намеренно.
 *
 * # Чего у него нет и не появится
 *
 * Ни базы, ни личности, ни истории. Всё, что он показывает, приехало
 * с телефона в этой связи или лежит в дисковом кэше с прошлой — и во втором
 * случае об этом сказано полем `fresh`. Выключенный телефон означает
 * нерабочий десктоп, и изображать обратное §14 запрещает прямо.
 */
open class RatatoskCompanion: Disposable, AutoCloseable, RatatoskCompanionInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_ratatosk_ffi_fn_free_ratatoskcompanion(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_ratatosk_ffi_fn_clone_ratatoskcompanion(handle, status)
        }
    }

    
    /**
     * Просит **телефон** начать качать вложение у собеседника.
     *
     * Порядок обязателен и его надо объяснять человеку: сперва телефон
     * забирает файл у собеседника, и только потом
     * [`RatatoskCompanion::save_file`] переносит его сюда. До `accept_file`
     * забирать нечего.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    @Throws(RatatoskException::class)override fun `acceptFile`(`fileId`: kotlin.ByteArray)
        = 
    callWithHandle {
    uniffiRustCallWithError(RatatoskException) { _status ->
    UniffiLib.uniffi_ratatosk_ffi_fn_method_ratatoskcompanion_accept_file(
        it,
        
        FfiConverterByteArray.lower(`fileId`),_status)
}
    }
    
    

    
    /**
     * Добавляет к себе того, чья карточка приехала этим сообщением.
     *
     * **Называется сообщение, а не карточка.** Байты лежат на телефоне
     * и границу не пересекают ни туда, ни обратно: присланная с десктопа
     * «карточка» была бы ключом, назначенным десктопом.
     *
     * Сверки (§4.2) это не даёт и дать не может: она делается голосом
     * при встрече, а не нажатием в окне.
     *
     * # Errors
     *
     * Идентификатор не той длины; карточки в этом сообщении нет —
     * телефон скажет словами.
     */
    @Throws(RatatoskException::class)override fun `addSharedContact`(`msgId`: kotlin.ByteArray)
        = 
    callWithHandle {
    uniffiRustCallWithError(RatatoskException) { _status ->
    UniffiLib.uniffi_ratatosk_ffi_fn_method_ratatoskcompanion_add_shared_contact(
        it,
        
        FfiConverterByteArray.lower(`msgId`),_status)
}
    }
    
    

    
    /**
     * Спрашивает аватарку — контакта или свою.
     *
     * `chat_id = None` — своя. Ответ приедет событием
     * [`FfiCompanionEvent::Avatar`], байтами, и мера у этого та же, что
     * у превью: лицо не больше 32 КиБ.
     *
     * **Звать стоит по метке, а не на каждый показ списка.**
     * [`FfiCompanionChat::avatar_ms`] говорит, изменилось ли лицо
     * с прошлого раза; спросив без этой проверки, окно возит по сети
     * тридцать два килобайта на контакт при каждом обновлении списка.
     * Свою — раз за подключение: метки для сравнения у неё нет.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    @Throws(RatatoskException::class)override fun `avatar`(`chatId`: kotlin.ByteArray?)
        = 
    callWithHandle {
    uniffiRustCallWithError(RatatoskException) { _status ->
    UniffiLib.uniffi_ratatosk_ffi_fn_method_ratatoskcompanion_avatar(
        it,
        
        FfiConverterOptionalByteArray.lower(`chatId`),_status)
}
    }
    
    

    
    /**
     * Прекращает начатое сохранение и убирает недописанный файл.
     *
     * Обрывок стирается всегда, и это не уборка ради чистоты: недокачанный
     * файл на диске выглядит ровно как докачанный (§14).
     *
     * # Errors
     *
     * Компаньон остановлен.
     */
    @Throws(RatatoskException::class)override fun `cancelSave`()
        = 
    callWithHandle {
    uniffiRustCallWithError(RatatoskException) { _status ->
    UniffiLib.uniffi_ratatosk_ffi_fn_method_ratatoskcompanion_cancel_save(
        it,
        _status)
}
    }
    
    

    
    /**
     * Передумывает отправлять: выгруженное на телефоне выбрасывается.
     *
     * # Errors
     *
     * Компаньон остановлен.
     */
    @Throws(RatatoskException::class)override fun `cancelSend`()
        = 
    callWithHandle {
    uniffiRustCallWithError(RatatoskException) { _status ->
    UniffiLib.uniffi_ratatosk_ffi_fn_method_ratatoskcompanion_cancel_send(
        it,
        _status)
}
    }
    
    

    
    /**
     * Просит список чатов.
     *
     * Ответ приедет событием [`FfiCompanionEvent::Chats`], а не отсюда:
     * считает его телефон, и ждать его синхронно значило бы держать окно
     * на круге по сети.
     *
     * # Errors
     *
     * Компаньон остановлен.
     */
    @Throws(RatatoskException::class)override fun `chats`()
        = 
    callWithHandle {
    uniffiRustCallWithError(RatatoskException) { _status ->
    UniffiLib.uniffi_ratatosk_ffi_fn_method_ratatoskcompanion_chats(
        it,
        _status)
}
    }
    
    

    
    /**
     * Очищает чат **у себя**.
     *
     * # Errors
     *
     * Негодный идентификатор или остановленный компаньон.
     */
    @Throws(RatatoskException::class)override fun `clearChat`(`chatId`: kotlin.ByteArray)
        = 
    callWithHandle {
    uniffiRustCallWithError(RatatoskException) { _status ->
    UniffiLib.uniffi_ratatosk_ffi_fn_method_ratatoskcompanion_clear_chat(
        it,
        
        FfiConverterByteArray.lower(`chatId`),_status)
}
    }
    
    

    
    /**
     * Заводит группу (§11).
     *
     * **Перед вызовом обязателен `group_join_notice()`.** §11.5 требует
     * сказать при создании, что участники увидят onion- и chatmail-адреса
     * друг друга; сказанное после — уже не предупреждение, а отменить это
     * нельзя ничем. Текст — свободная функция тех же биндингов: проводом
     * он не едет, потому что это константа, а не сведение о телефоне,
     * и телефон не может проверить, показали ли его.
     *
     * Идентификатор новой группы придёт событием
