    @Throws(RatatoskException::class) fun `open`(`inviteUri`: kotlin.String, `port`: kotlin.UShort, `peerAddr`: kotlin.String?, `cachePath`: kotlin.String?, `torDir`: kotlin.String?): RatatoskCompanion {
