/**
 * Наибольший размер файла, который поедет почтой (§10.3).
 *
 * Файл крупнее ждёт прямого канала: почтой он поехал бы сутками, и §14
 * велит сказать это до начала, а не показывать полосу, которая
 * не сдвинется. Ограничение это про **время**, а не про место — место
 * защищает окно передачи.
 *
 * Клиенту нужно, чтобы сказать заранее. Без этого числа он узнаёт
 * о запрете только событием [`FfiEvent::FileWaitsForChannel`], то есть
 * уже после того, как человек выбрал файл и нажал «отправить».
 *
 * Заведомо меньше [`max_file_bytes`]: прямым каналом ходит всё.
 * Чем открывают архив (§12).
 *
 * Два входа в один и тот же архив. Фразу человек придумал сам и держит
 * в голове; сырой ключ он положил в менеджер паролей и не смотрит на него
 * никогда. Спрашивать надо **тот, который подойдёт**, — что подойдёт,
 * говорит [`peek_archive`].
 */
sealed class FfiArchiveUnlock {
    
    /**
     * Фраза, придуманная при вывозе.
     */
    data class Passphrase(
        /**
         * Она самая.
         */
        val `phrase`: kotlin.String) : FfiArchiveUnlock()
        
    {
        

        companion object
    }
    
    /**
     * Сырой ключ — та строка, что показывалась при вывозе.
     */
    data class Key(
        /**
         * Разделители и регистр не важны.
         */
        val `keyText`: kotlin.String) : FfiArchiveUnlock()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiArchiveUnlock : FfiConverterRustBuffer<FfiArchiveUnlock>{
    override fun read(buf: ByteBuffer): FfiArchiveUnlock {
        return when(buf.getInt()) {
            1 -> FfiArchiveUnlock.Passphrase(
                FfiConverterString.read(buf),
                )
            2 -> FfiArchiveUnlock.Key(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiArchiveUnlock): ULong = when(value) {
        is FfiArchiveUnlock.Passphrase -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`phrase`)
            )
        }
        is FfiArchiveUnlock.Key -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`keyText`)
            )
        }
    }

    override fun write(value: FfiArchiveUnlock, buf: ByteBuffer) {
        when(value) {
            is FfiArchiveUnlock.Passphrase -> {
                buf.putInt(1)
                FfiConverterString.write(value.`phrase`, buf)
                Unit
            }
            is FfiArchiveUnlock.Key -> {
                buf.putInt(2)
                FfiConverterString.write(value.`keyText`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * Что компаньон говорит окну.
 */
sealed class FfiCompanionEvent {
    
    /**
     * Сессия с телефоном установлена.
     */
    object Linked : FfiCompanionEvent()
    
    
    /**
     * Канала больше нет.
     *
     * §14, пункт 5: телефона нет — десктоп не работает. Показывать это
     * обязательно, а не молча оставлять последний экран: он выглядит
     * точно так же, как живой.
     */
    object Unlinked : FfiCompanionEvent()
    
    
    /**
     * Каким проводом говорит телефон.
     *
     * Приходит один раз при подключении и **только при расхождении**:
     * «всё в порядке» на каждом подключении приучает не читать эту строку.
     * `theirs = None` означает сборку телефона старее самого вопроса.
     */
    data class Wire(
        /**
         * Что назвал телефон.
         */
        val `theirs`: kotlin.UInt?, 
        /**
         * Что здесь.
         */
        val `ours`: kotlin.UInt) : FfiCompanionEvent()
        
    {
        

        companion object
    }
    
    /**
     * Список чатов.
     */
    data class Chats(
        /**
         * Чаты.
         */
        val `chats`: List<org.ratatosk.core.FfiCompanionChat>, 
        /**
         * Подтверждён ли телефоном в этой связи.
         *
         * `false` — это память с прошлого раза (дисковый кэш). Показывать
         * её можно, выдавать за сейчас — нет: стёртое на телефоне при
         * выключенном ноутбуке лежит в ней целым.
         */
        val `fresh`: kotlin.Boolean) : FfiCompanionEvent()
        
    {
        

        companion object
    }
    
    /**
     * Страница истории, от старых к новым.
     */
    data class History(
        /**
         * Какого чата.
         */
        val `chatId`: kotlin.ByteArray, 
        /**
         * Сообщения.
         */
        val `page`: List<org.ratatosk.core.FfiCompanionMessage>, 
        /**
         * Подтверждена ли телефоном в этой связи.
         */
        val `fresh`: kotlin.Boolean) : FfiCompanionEvent()
        
    {
        

        companion object
    }
    
    /**
     * Пришло сообщение.
     */
    data class Arrived(
        /**
         * Оно.
         */
        val `message`: org.ratatosk.core.FfiCompanionMessage) : FfiCompanionEvent()
        
    {
        

        companion object
    }
    
    /**
     * Сменился статус доставки.
     */
    data class StatusChanged(
        /**
         * Какого сообщения.
         */
        val `msgId`: kotlin.ByteArray, 
        /**
         * Новый.
         */
        val `status`: org.ratatosk.core.FfiDeliveryStatus) : FfiCompanionEvent()
        
    {
        

        companion object
    }
    
    /**
     * Список чатов изменился — перечитать [`RatatoskCompanion::chats`].
     */
    object ChatsChanged : FfiCompanionEvent()
    
    
    /**
     * Сообщений больше нет — убрать со страницы.
     */
    data class Gone(
        /**
         * В каком чате.
         */
        val `chatId`: kotlin.ByteArray, 
        /**
         * Каких.
         */
        val `msgIds`: List<kotlin.ByteArray>) : FfiCompanionEvent()
        
    {
        

        companion object
    }
    
    /**
     * Сообщение поправили — вот оно целиком.
     */
    data class Edited(
        /**
         * Оно.
         */
        val `message`: org.ratatosk.core.FfiCompanionMessage) : FfiCompanionEvent()
        
    {
        

        companion object
    }
    
    /**
     * У сообщения сменился набор реакций.
     */
    data class Reacted(
        /**
         * В каком чате.
         */
        val `chatId`: kotlin.ByteArray, 
        /**
         * На каком сообщении.
         */
        val `msgId`: kotlin.ByteArray, 
        /**
         * Все реакции сейчас — набор целиком, а не дополнение.
         */
        val `reactions`: List<org.ratatosk.core.FfiCompanionReaction>) : FfiCompanionEvent()
        
    {
        

        companion object
    }
    
    /**
     * У вложения на телефоне сдвинулся приём.
     */
    data class FileProgress(
        /**
         * Какого.
         */
        val `fileId`: kotlin.ByteArray, 
        /**
         * Сколько кусков у телефона.
         */
        val `haveChunks`: kotlin.ULong, 
        /**
         * Сколько всего.
         */
        val `chunkTotal`: kotlin.ULong, 
        /**
         * Согласен ли телефон качать его сейчас.
         */
        val `accepted`: kotlin.Boolean) : FfiCompanionEvent()
        
    {
        

        companion object
    }
    
    /**
     * Вложения больше нет — убрать строку, оставив сообщение.
     *
     * Отдельное событие, а не нули в [`FfiCompanionEvent::FileProgress`]:
     * число не может значить «чисел больше не будет», и пустой файл давал
     * ровно те же нули.
     */
    data class FileGone(
        /**
         * Какого.
         */
        val `fileId`: kotlin.ByteArray) : FfiCompanionEvent()
        
    {
        

        companion object
    }
    
    /**
     * Превью вложения (§10.3) — или его отсутствие.
     *
     * `bytes: None` — превью нет, и это **ответ, а не отказ**: вложение без
     * картинки обычное дело. Рисовать нечего, и говорить об этом человеку
     * незачем.
     *
     * Не больше 32 КиБ — предел проверен проводом, но декодировать эти
     * байты всё равно клиенту, и декодер изображений — большая поверхность
     * атаки. Картинка пришла с чужого телефона: обращаться с ней надо как
     * с любым чужим файлом, а не как со своим ресурсом.
     */
    data class FilePreview(
        /**
         * Какого вложения.
         */
        val `fileId`: kotlin.ByteArray, 
        /**
         * Байты, если они есть.
         */
        val `bytes`: kotlin.ByteArray?) : FfiCompanionEvent()
        
    {
        

        companion object
    }
    
    /**
     * Аватарка — или её отсутствие.
     *
     * `bytes: None` — показывать нечего: аватарки нет либо контакт
     * не сверен (§4.2). Случаи неразличимы намеренно, рисовать в обоих
     * надо одно.
     *
     * Не больше 32 КиБ — предел проверен проводом, но декодировать эти
     * байты всё равно клиенту, и с чужого телефона они пришли ровно так же,
     * как превью: обращаться с ними надо как с любым чужим файлом.
     */
    data class Avatar(
        /**
         * Чей чат; `None` — своя.
         */
        val `chatId`: kotlin.ByteArray?, 
        /**
         * Байты, если они есть.
         */
        val `bytes`: kotlin.ByteArray?, 
        /**
         * Подтверждено ли телефоном сейчас; `false` — показанное из кэша.
         */
        val `fresh`: kotlin.Boolean) : FfiCompanionEvent()
        
    {
        

        companion object
    }
    
    /**
     * Состав группы (§11.2) — в ответ на [`RatatoskCompanion::members`].
     *
     * Признака `fresh` здесь нет, и это не пропуск: состав не кэшируется,
     * а значит приходит только от телефона и только сейчас. Пустой список
     * — законный ответ: так отвечает личный чат.
     */
    data class Members(
        /**
         * Какой группы.
         */
