/**
 * Ошибка, которую видит клиент.
 *
 * Формулировки скупые и не раскрывают, что именно не сошлось: подробная
 * ошибка на границе рано или поздно оказывается в логе, а оттуда — у того,
 * от кого §2.1 обещает защиту.
 */
sealed class RatatoskException: kotlin.Exception() {
    
    /**
     * База заблокирована: нужен PIN (§8.6).
     */
    class Locked(
        ) : RatatoskException() {
        override val message
            get() = ""
    }
    
    /**
     * Внутренняя ошибка.
     */
    class Internal(
        
        /**
         * Короткое описание для отчёта.
         */
        val `reason`: kotlin.String
        ) : RatatoskException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<RatatoskException> {
        override fun lift(error_buf: RustBuffer.ByValue): RatatoskException = FfiConverterTypeRatatoskError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeRatatoskError : FfiConverterRustBuffer<RatatoskException> {
    override fun read(buf: ByteBuffer): RatatoskException {
        

        return when(buf.getInt()) {
            1 -> RatatoskException.Locked()
            2 -> RatatoskException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RatatoskException): ULong {
        return when(value) {
            is RatatoskException.Locked -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is RatatoskException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: RatatoskException, buf: ByteBuffer) {
        when(value) {
            is RatatoskException.Locked -> {
                buf.putInt(1)
                Unit
            }
            is RatatoskException.Internal -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalUInt: FfiConverterRustBuffer<kotlin.UInt?> {
    override fun read(buf: ByteBuffer): kotlin.UInt? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUInt.read(buf)
    }

    override fun allocationSize(value: kotlin.UInt?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUInt.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UInt?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterUInt.write(value, buf)
        }
    }
}




